/**
 * Hero demo assets. Every image here is a DEVELOPMENT FIXTURE: hand-authored vector art made by
 * `scripts/hero-demo-art.mjs`. None of it is StoryPanel output, and none was generated by an AI provider.
 * Replace each entry with approved artwork (generated by StoryPanel and cleared for marketing) before
 * claiming the demo shows real product output; keep the same purpose and aspect ratio.
 */
export type DemoAsset = { id: string; src: string; purpose: string; width: number; height: number; status: "development-fixture" | "approved" };

export const DEMO_ASSETS: Record<"keeper" | "gull" | "panel1" | "panel2" | "panel3", DemoAsset> = {
  keeper: { id: "keeper", src: "/hero-demo/cast-keeper.svg", purpose: "Cast reference portrait: lighthouse keeper (yellow raincoat, navy knit cap, round glasses)", width: 400, height: 480, status: "development-fixture" },
  gull: { id: "gull", src: "/hero-demo/cast-gull.svg", purpose: "Cast reference portrait: gull (white body, grey wings, orange beak)", width: 400, height: 480, status: "development-fixture" },
  panel1: { id: "panel1", src: "/hero-demo/panel-1.svg", purpose: "Panel 1, wide: the keeper notices the shivering gull in the rain (no shell)", width: 580, height: 400, status: "development-fixture" },
  panel2: { id: "panel2", src: "/hero-demo/panel-2.svg", purpose: "Panel 2, medium: the keeper places the blue shelter (no shell)", width: 580, height: 400, status: "development-fixture" },
  panel3: { id: "panel3", src: "/hero-demo/panel-3.svg", purpose: "Panel 3, close-up payoff: the gull inside the shelter; the keeper holds the shell", width: 1120, height: 460, status: "development-fixture" },
};

/** True only when every asset is approved for public marketing use. */
export const allApproved = () => Object.values(DEMO_ASSETS).every((a) => a.status === "approved");
